function expNeeded(){
  const lv=player.level;
  // —— 梯度成长曲线：前期轻快，中段渐陡，后期陡峭但破境回档 ——
  // 境界门槛（REALMS.lv）处回档一截，形成"破境→平台→再陡"的阶梯
  let base;
  if(lv<3)      base= 60 + lv*45;              // 1-2：105→150
  else if(lv<6) base= 180 + (lv-3)*70;         // 3-5：180→320
  else if(lv<9) base= 420 + (lv-6)*120;        // 6-8：420→660
  else if(lv<13)base= 820 + (lv-9)*170;        // 9-12：820→1330
  else if(lv<16)base=1500 + (lv-13)*220;       // 13-15：1500→1940
  else if(lv<20)base=2300 + (lv-16)*280;       // 16-19：2300→3140
  else if(lv<24)base=3500 + (lv-20)*340;       // 20-23：3500→4520
  else if(lv<28)base=4800 + (lv-24)*400;       // 24-27：4800→6400
  else if(lv<32)base=6600 + (lv-28)*460;       // 28-31：6600→8440
  else if(lv<36)base=8800 + (lv-32)*520;       // 32-35：8800→10880
  else          base=11400 + (lv-36)*580;      // 36+：11400→
  // 破境回档：恰好站在某境界门槛时，经验需求回落（鼓励破境、形成阶梯）
  for(let i=0;i<REALMS.length;i++){ if(lv===REALMS[i].lv){ base=Math.max(80, base-450); break; } }
  return Math.floor(base);
}
```

