function daoBonus(){
  let hp=0, mp=0, atk=0, def=0, skill=0;
  for(const k of DAO_NAMES){
    const lv=daoLv(k); const b=PATHS[k].bonus;
    hp+=b.hp*lv; mp+=b.mp*lv; atk+=b.atk*lv; def+=b.def*lv; skill+=b.skill*lv;
  }
  // —— 数值平衡：道途增益设上限，防止兼修到后期成倍膨胀 ——
  atk=Math.min(atk, 0.4);   // 攻击加成上限 +40%
  skill=Math.min(skill, 0.28); // 术法加成上限 +28%
  return {hp:hp, mp:mp, atk:atk, def:def, skill:skill};
}
```

