```js
function genStartupPackage(lv, bg){
  const tier= lv>=15?3 : lv>=9?2 : lv>=6?1 : 0;
  // ========== 1) 人物关系网：普通开局也有一群"认得你的人" ==========
  const homeZone= bg&&bg.spot ? (START_SPOTS.find(function(s){return s.id===bg.spot;})||{}).zone : null;
  const homeArea= player.room&&ROOMS[player.room] ? ROOMS[player.room].area : null;
  const base=Object.keys(NPCS).filter(function(n){
    const npc=NPCS[n];
    return npc && !npc.boss && npc.canKill!==false && npc.special!==true && !game.npcDead[n] && n!==player.name;
  });
  // 同乡优先：同出生地/同大洲的人物，天然该先认得你
  const locals=base.filter(function(n){
    const npc=NPCS[n];
    const z= homeZone && npc.zone===homeZone;
    const a= homeArea && npc.home && String(npc.home).indexOf(homeArea)>-1;
    return z||a;
  });
  const pool= locals.length>=2 ? locals : base;
  if(pool.length){
    const relCount=Math.min(pool.length, Math.max(3, 3+tier));
    const used={};
    let made=0, close=0;
    for(let i=0;i<relCount;i++){
      let n=jp(pool), t2=0;
      while(used[n] && t2<10){ n=jp(pool); t2++; }
      used[n]=true;
      const npc=NPCS[n];
      const local=(bg&&bg.aff&&bg.aff[n])?true:false;
      const kind=Math.random();
      let aff=0, note='', rel='';
      if(local){ aff=Math.max(25, bg.aff[n]); note='从小便认得你——街坊故里，知根知底'; rel='好友'; }
      else if(kind<0.4){ aff=10+tier*6+Math.floor(RNG()*10); note='与你有些旧交，见面便熟络'; rel=''; }
      else if(kind<0.75){ aff=18+tier*8+Math.floor(RNG()*12); note='久闻你的名头，一见便以礼相待'; rel=''; }
      else { aff=25+tier*10+Math.floor(RNG()*14); note='曾受你照拂，对你心折，颇有结交之意'; rel='好友'; }
      if(!player.aff) player.aff={};
      player.aff[n]=Math.max(player.aff[n]||0, Math.min(90,aff));
      // 深交者记入"好友"名册（开局就有一两位知根知底的人）
      if(rel && aff>=22 && close<2){
        if(!player.relation) player.relation={};
        if(!player.relation[n]){ player.relation[n]=rel; close++; }
      }
      logInfo('（你初入江湖，'+(npc.title||'一位人物')+' '+n+' 却已认得你——'+note+'。好感 +'+aff+'）');
      made++;
    }
