```js
  // ========== 1) 人物关系网：普通开局也有一群"认得你的人" ==========
  const basePool=Object.keys(NPCS).filter(function(n){
    const npc=NPCS[n];
    return npc && !npc.boss && npc.canKill!==false && npc.special!==true && !game.npcDead[n] && n!==player.name;
  });
  if(basePool.length){
    // 同乡优先：与出生地同洲/同坊的人物，天然该先认得你（找不到再用大池）
    const _spot=bg&&bg.spot ? (START_SPOTS.find(function(s){return s.id===bg.spot;})||null) : null;
    const _homeZone=_spot?_spot.zone:null;
    const _homeArea= (player.room&&ROOMS[player.room])?ROOMS[player.room].area:null;
    const locals=basePool.filter(function(n){
      const npc=NPCS[n];
      if(!npc) return false;
      if(_homeZone && npc.zone===_homeZone) return true;
      if(_homeArea && npc.home && String(npc.home).indexOf(_homeArea)>-1) return true;
      return false;
    });
    const pool= locals.length>=2 ? locals : basePool;
    // 关系数量：最低 3 个（街坊/故交），境界越高认识的人越多
    const relCount=Math.min(pool.length, Math.max(3, 3+tier));
    const used={};
    let made=0, close=0;
    for(let i=0;i<relCount;i++){
      let n=jp(pool), t2=0;
      while(used[n] && t2<10){ n=jp(pool); t2++; }
      used[n]=true;
      const npc=NPCS[n];
      // 优先找与出生地沾边的NPC（同乡/同坊），找不到再随缘
      const kind=Math.random();
      let aff=0, note='', rel='';
      const local=(bg&&bg.aff&&bg.aff[n])?true:false;
      if(local){ aff=Math.max(25, bg.aff[n]); note='从小便认得你——街坊故里，知根知底'; rel='好友'; }
      else if(kind<0.4){ aff=10+tier*6+Math.floor(RNG()*10); note='与你有些旧交，见面便熟络'; }
      else if(kind<0.75){ aff=18+tier*8+Math.floor(RNG()*12); note='久闻你的名头，一见便以礼相待'; }
      else { aff=25+tier*10+Math.floor(RNG()*14); note='曾受你照拂，对你心折，颇有结交之意'; rel='好友'; }
      if(!player.aff) player.aff={};
      player.aff[n]=Math.max(player.aff[n]||0, Math.min(90,aff));
      // 深交者记入"好友"名册（开局就有一两位知根知底的人，才像有来处）
      if(rel && aff>=22 && close<2){
        if(!player.relation) player.relation={};
        if(!player.relation[n]){ player.relation[n]=rel; close++; }
      }
      logInfo('（你初入江湖，'+(npc.title||'一位人物')+' '+n+' 却已认得你——'+note+'。好感 +'+aff+'）');
      made++;
    }
    if(tier>=2){
      const fameAdd=(tier-2)*12+5;
      gainFame(fameAdd);
      logInfo('（高境入世，名望自随——江湖传你之名，侠名 +'+fameAdd+'。）');
    }
  }
```

Wait — there's a subtle bug risk: `locals.length>=2 ? locals : basePool` — if locals.length is 1, we use basePool, fine. If locals.length>=2, we only pick from locals (could be exactly 2, but relCount could be 3+ for tier>=1 → then jp(pool) picks with replacement but used[n] guard retries 10 times and could fail to find unique → could pick duplicates). For locals of size 2 and relCount 3, the while loop retries but pool only has 2 unique → used[n] stays true → after 10 tries it still returns a used one → duplicate relations (aff set twice, log twice). Not fatal but ugly. To be safe, cap relCount by pool.length (already: Math.min(pool.length, ...)). Yes: `Math.min(pool.length, Math.max(3,3+tier))` — so if pool.length is 2, relCount=2. Good — no duplicates. And if locals.length=1 we fall to basePool (large). Good.

But wait: if locals.length>=2 but pool=locals with length 2, relCount=2 — that gives only 2 relations for a normal start, slightly under "at least 3". Hmm. Let me change the locals check to `locals.length>=3 ? locals : basePool`. That guarantees at least 3 unique candidates when using locals. If a spot has only 2 same-zone NPCs, fall back to base pool (which will naturally include some locals among many). Good.

