  "https://codeload.github.com/jianlai-wiki/jianlai/tar.gz/refs/heads/main",
  "https://gitee.com/jianlai-wiki/jianlai/repository/archive/main.zip",
  "https://raw.githubusercontent.com/jianlai-wiki/jianlai/master/README.md"
)
foreach($u in $tests){
  try {
    $r = Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 12 -Headers @{"User-Agent"="Mozilla/5.0"}
    Write-Output ("OK  "+$u+"  len="+$r.Content.Length+" status="+$r.StatusCode)
  } catch { Write-Output ("ERR "+$u+" : "+$_.Exception.Message) }
}","description":"Try more wiki fetch routes"}

