{"file_path": "F:\1\jianlai\JianLai mud\index.html", "new_string": "  'lz2':{ title:'骊珠旧事·二·故人之伤', giver:'齐静春', desc:'（长支线）云来客栈的刘羡阳重伤垂危——正阳山的搬山猿，为一本祖传剑经下的毒手。去见他一面。', target:{type:'talk', what:'刘羡阳', need:1}, reward:{exp:90,gold:60}, turnin:'齐静春',
    acceptLines:['（齐静春罕见地锁着眉，檐下灯笼的光把他的影子拉得很长）刘羡阳，云来客栈那个少年剑客——被正阳山的搬山猿重伤，吊着一口气。','（他低声道）那畜牲，为的是一部祖传剑经。陈平安当年与宁姚合战此獠，逼它在小镇换了三口气，才救下这条命。你先去看看他。'],
    acceptOptions:[
      { text:'欺人太甚——我去看看刘兄。', effect:function(){ log('（齐静春点了点头：有情有义，这一趟你去，不冤枉。','npc','齐静春'); }, aff:10, fame:2 },
      { text:'正阳山……这笔账，我记下了。', effect:function(){ log('（齐静春看了你一眼，没有接话，只轻声道：记下就好。','npc','齐静春'); }, aff:8, exp:20 },
      { text:'救与不救，与我何干？', effect:function(){ log('（齐静春沉默片刻：江湖上的账，今日不欠，来日也要还的。','npc','齐静春'); }, aff:-6, gold:20 }
    ],
    turnLines:['（你从云来客栈回来，齐静春坐在书案后，指尖轻轻叩着桌沿）见着了？','（他抬眼看你，目光平静）那部剑经还在正阳山手里。搬山猿，藏在蛮荒妖寨。'],
    turnOptions:[
      { text:'刘兄虽伤，心气未折——这口气，我替他出。', effect:function(){ log('（齐静春点头：好。正阳山的账，该有人去算了。','npc','齐静春'); }, bonus:{fame:4, aff:6, affNpc:'齐静春'} },
      { text:'他若撑不过去……这笔账，更要算清。', effect:function(){ log('（齐静春望着窗外，轻声道：那便算清。','npc','齐静春'); }, bonus:{expMul:1.2, fame:2} }
    ] },
  'lz3':{ title:'骊珠旧事·三·正阳山问罪', giver:'齐静春', desc:'（长支线）正阳山的搬山猿为祸一方——重伤刘羡阳、夺其剑经的正是此獠。斩之，宝瓶洲为之震动。', target:{type:'kill', what:'搬山猿', need:1}, reward:{exp:160,gold:100,item:'五行精粹'}, turnin:'齐静春',
    acceptLines:['（齐静春摊开一幅泛黄的山舆图，指尖点在一处）蛮荒妖寨，搬山猿的老巢——宝瓶洲的商路，断在这畜牲手里。','（他抬眼看你）妖寨凶险，此去九死一生。你，可还愿意走这一趟？'],
    acceptOptions:[
      { text:'剑已出鞘，没有收回的道理。', effect:function(){ log('（齐静春看着你，缓缓点头：好。这一剑，替你记在浩然的名册上。','npc','齐静春'); }, aff:10, fame:2 },
      { text:'为刘羡阳讨一个公道。', effect:function(){ log('（齐静春目光柔和了些：懂恩怨，才懂大义。','npc','齐静春'); }, aff:8, fame:3 },
      { text:'赏钱够厚，我便去。', effect:function(){ log('（齐静春沉默了一瞬，还是道：重赏之下，亦有勇夫。','npc','齐静春'); }, gold:30, aff:-4 }
    ],
    turnLines:['（搬山猿伏诛，消息如惊雷滚过宝瓶洲。齐静春立于渡口，负手望着江水，良久无言）','（他转过身，眼中有一丝复杂的光）这一剑，劈开的不止是妖寨——是蛮荒的气焰。刘羡阳的剑经，老夫已托人送回云来客栈。'],
    turnOptions:[
      { text:'妖寨已平，剑经归主。', effect:function(){ log('（齐静春颔首：好。','npc','齐静春'); }, bonus:{fame:3} },
      { text:'我留了几个小妖的性命，教它们迁徙别处。', effect:function(){ log('（齐静春怔了怔，深深看你一眼：杀伐之中存仁心，难得。','npc','齐静春'); }, bonus:{fame:8} }
    ] },
  'lz4':{ title:'骊珠旧事·四·书院之路', giver:'齐静春', desc:'（长支线）骊珠洞天的太平不会长久——齐静春托你看顾一株读书种子：山崖书院的小学生李宝瓶。', target:{type:'talk', what:'李宝瓶', need:1}, reward:{exp:110,gold:80}, turnin:'齐静春',
    acceptLines:['（齐静春负手立在书院门口，望着操场上追着纸鸢跑的少女，神色平静）骊珠洞天看着太平，可天底下的太平，从没有白来的。','（他轻声道）李宝瓶，是我选中的读书种子。将来若有一日，你要替老夫送她出骊珠，去山崖书院——读万卷书，行万里路。先替我去看看她。'],
    acceptOptions:[
      { text:'读书种子，我记下了。', effect:function(){ log('（齐静春点头：记得就好。她唤陈平安一声小师叔，你将来，说不定也能当她的师兄。','npc','齐静春'); }, aff:10, fame:2 },
      { text:'为何选中她？', effect:function(){ log('（齐静春望着远处：这丫头读书，读到了心里去。书上的道理，会长脚，走进人肚子里。','npc','齐静春'); }, aff:8, exp:25 },
      { text:'护人？我自己都护不住自己。', effect:function(){ log('（齐静春笑了笑：护得住一个，已是天大的本事。','npc','齐静春'); }, aff:4 }
    ],
    turnLines:['（你从山崖书院回来，齐静春正在檐下煮茶，像是早已料到你会带回什么消息）宝瓶那丫头，又缠着人讲故事了？','（他递给你一盏茶，声音温和）读万卷书，行万里路——她的路，还长着。你的路，也不短。'],
    turnOptions:[
      { text:'她问我是不是小师叔派来的——我说是。', effect:function(){ log('（齐静春哑然失笑：那丫头，机灵得很。也好，让她多记你一分。','npc','齐静春'); }, bonus:{fame:4, aff:6, affNpc:'李宝瓶'} },
      { text:'她背了半本《问剑》，一字不差。', effect:function(){ log('（齐静春眼中浮起一丝欣慰：这株种子，没有选错。','npc','齐静春'); }, bonus:{expMul:1.2, fame:3} }
    ] },
  'lz5':{ title:'骊珠旧事·五·老剑条', giver:'齐静春', desc:'（长支线）藕花福地深处藏着一柄上古残剑——老剑条。它的剑灵，与一段旧日江湖有关。去听一听。', target:{type:'talk', what:'剑灵老妪', need:1}, reward:{exp:140,gold:100,item:'谷雨钱'}, turnin:'齐静春',
    acceptLines:['（齐静春从袖中取出一截枯枝般的剑穗，摩挲良久）剑气长城有柄老剑条，随古天庭旧事流落人间，如今剑灵栖在藕花福地深处。','（他低声道）当年老夫曾为它，向道祖讨来一株遮掩天机的荷花。你去福地深处，见一见守剑人——听一段旧事，也是替浩然记一笔账。'],
    acceptOptions:[
      { text:'老剑条的旧事，我想听。', effect:function(){ log('（齐静春点头：好。剑有剑的缘法，人有人的缘法。','npc','齐静春'); }, aff:8, fame:2 },
      { text:'一柄残剑，也值得道祖出手？', effect:function(){ log('（齐静春看了你一眼：那剑里，住着一位比老夫年长许多的前辈。','npc','齐静春'); }, aff:6, exp:30 },
      { text:'要听旧事，得加钱。', effect:function(){ log('（齐静春失笑，还是多给了几两：行商可以，莫要行义也论价。','npc','齐静春'); }, gold:25, aff:-4 }
    ],
    turnLines:['（你从藕花福地归来，齐静春正在院中扫落叶，帚声沙沙）见着那柄剑了？','（他停下扫帚，直起身）剑灵前辈脾气大，肯见你，是缘分。老剑条迟早要认主——至于是谁，看天意，也看人心。'],
    turnOptions:[
      { text:'她说我是"有鞘的剑"——剑未出鞘，先有担当。', effect:function(){ log('（齐静春怔了怔，随即笑了：这评语，老夫当年可没混到过。','npc','齐静春'); }, bonus:{fame:6, aff:6, affNpc:'剑灵老妪'} },
      { text:'她一句话都没说，只让我看了看那截剑穗。', effect:function(){ log('（齐静春点头：看得懂剑穗的人，自然看得懂剑。','npc','齐静春'); }, bonus:{expMul:1.2} }
    ] },
  'lz6':{ title:'骊珠旧事·六·王座伏诛', giver:'齐静春', desc:'（长支线）妖族祭坛的王座大妖萧初升蠢蠢欲动——诛之，以绝后患。', target:{type:'kill', what:'萧初升', need:1}, reward:{exp:260,gold:180,item:'夜明珠'}, turnin:'齐静春',
    acceptLines:['（齐静春遥望妖族祭坛方向，眉宇间难得地凝重起来）萧初升，王座大妖，野心比妖身更庞大。','（他沉声道）此妖若成气候，蛮荒与浩然的平衡，便要倾覆。诛之，以绝后患——你，敢接么？'],
    acceptOptions:[
      { text:'王座又如何——剑下无贵贱。', effect:function(){ log('（齐静春眼中精光一闪：好胆气。','npc','齐静春'); }, aff:10, fame:2 },
      { text:'为浩然守这道太平，责无旁贷。', effect:function(){ log('（齐静春拱手一礼：浩然天下，记你这一剑。','npc','齐静春'); }, aff:12, fame:4 },
      { text:'若我败了，你可有后手？', effect:function(){ log('（齐静春平静道：你若败了，浩然便再无人敢接这一剑——所以，你最好胜。','npc','齐静春'); }, aff:3, exp:30 }
    ],
    turnLines:['（萧初升伏诛的捷报传回，齐静春在书院檐下站了许久，像是在替谁默念。终于，他开口）王座已坠，蛮荒自乱。','（他看向你，声音里有一丝不易察觉的倦意，也有一丝欣慰）这一段旧事，终于要走到头了。'],
    turnOptions:[
      { text:'王座已坠，浩然可安。', effect:function(){ log('（齐静春点头：还有最后一桩——剑气长城。','npc','齐静春'); }, bonus:{fame:4} },
      { text:'萧初升死前，求我把一句话带给你。', effect:function(){ log('（齐静春微微一怔：……什么话？', 'npc','齐静春'); }, bonus:{fame:6} }
    ] },
  'lz7':{ title:'骊珠旧事·七·十年之约', giver:'齐静春', desc:'（长支线）剑气长城之巅，老剑仙陈清都守了千年。齐静春说：你该去城头，听一听那场"十年之约"的旧事了。', target:{type:'reach', what:'剑气长城城头', need:1}, reward:{exp:320,gold:200}, turnin:'齐静春',
    acceptLines:['（齐静春凭栏远眺，山风掀起他的衣袍）剑气长城——浩然与蛮荒的分界，老剑仙陈清都守了千年，守的是城后那万家灯火。','（他转头看你）长城之上，有一场十年之约，一段问心旧事。你去城头站一站，替老夫，也替你自己，听一听风声。'],
    acceptOptions:[
      { text:'守城千年——这样的人，我该去见。', effect:function(){ log('（齐静春目光深远：见了，你就知道，什么叫"当仁不让"。','npc','齐静春'); }, aff:10, fame:3 },
      { text:'十年之约……是谁与谁的约？', effect:function(){ log('（齐静春沉默片刻：是剑与心，是旧人与旧事。到了城头，自有人讲给你听。','npc','齐静春'); }, aff:6, exp:35 },
      { text:'长城风大，我身子骨弱。', effect:function(){ log('（齐静春失笑：风大，才站得直。','npc','齐静春'); }, aff:2, gold:20 }
    ],
    turnLines:['（你从剑气长城城头归来，衣襟上还带着城头的风沙。齐静春看着你，半晌无言）城头的风，够烈罢？','（他轻声道）陈清都那一剑，压了千年。你站过城头，便该明白——有些人的守，比山还重。'],
    turnOptions:[
      { text:'老剑仙说：持剑者，当守天下。', effect:function(){ log('（齐静春眼中浮起一丝光：这话，他当年也同我说过。','npc','齐静春'); }, bonus:{fame:8, aff:8, affNpc:'陈清都'} },
      { text:'我在城头站了一夜——什么也没等到。', effect:function(){ log('（齐静春轻轻道：等不到，也是一种等。长城千年，等的就是一个"来日"。','npc','齐静春'); }, bonus:{expMul:1.2, fame:3} }
    ] },
  'lz8':{ title:'骊珠旧事·终·问鼎托月山', giver:'齐静春', desc:'（长支线·终）剑气长城之巅的托月山大祖，是旧日天下的最后一战——此战了结，浩然承平。', target:{type:'kill', what:'托月山大祖', need:1}, reward:{exp:600,gold:400,item:'神兽精血',skill:'养剑术'}, turnin:'齐静春',
    acceptLines:['（剑气长城之巅的风，烈得像刀。齐静春与你并肩而立，望着云海尽头的托月山）托月山大祖，蛮荒共主——这是旧日天下的最后一战。','（他转头看你，目光澄澈）此战了结，浩然承平。你，准备好了么？'],
    acceptOptions:[
      { text:'养兵千日，用兵一时——剑已饥渴。', effect:function(){ log('（齐静春目光灼灼：好。这一战，替你名留浩然。','npc','齐静春'); }, aff:10, fame:2 },
      { text:'为这天下，走最后一程。', effect:function(){ log('（齐静春久久无言，最后只轻轻道：多谢。','npc','齐静春'); }, aff:12, fame:5 },
      { text:'胜了如何？败了又如何？', effect:function(){ log('（齐静春望着远方：胜了，浩然承平；败了，浩然依旧——只是多了一段说不出口的旧事。','npc','齐静春'); }, aff:6, exp:40 }
    ],
    turnLines:['（托月山巅一战，云海为之开。齐静春站在长城的尽头，看着你一步步走回来，山风掀起他的衣袍）','（他沉默了很久，声音在风里格外清晰）旧日天下，自此了却。这一程，多谢你，替浩然走完。'],
    turnOptions:[
      { text:'剑已归鞘——浩然承平，我便去走我自己的路了。', effect:function(){ log('（齐静春看着你，忽然笑了：好。走你自己的路去罢——若迷了路，回骊珠来，还有人给你掌灯。','npc','齐静春'); }, bonus:{fame:6} },
      { text:'这一剑，是你教的——如今，我还给你。', effect:function(){ log('（齐静春怔了很久，忽然深深一揖：这一礼，替浩然天下行的。','npc','齐静春'); }, bonus:{fame:12, aff:10, affNpc:'齐静春'} }
    ] }", "old_string": "  'lz2':{ title:'骊珠旧事·二·剑镇妖寨', giver:'齐静春', desc:'（长支线）正阳山的搬山猿为祸一方，当年曾为一部剑经重伤刘羡阳——斩之，宝瓶洲为之震动。', target:{type:'kill', what:'搬山猿', need:1}, reward:{exp:150,gold:100,item:'五行精粹'}, turnin:'齐静春',
