{"file_path": "F:\1\jianlai\JianLai mud\index.html", "new_string": "    ] },
  // —— 原著人物委托 ——
  '铸剑':{ title:'三十年一剑', giver:'阮邛', desc:'骑龙巷的铁匠阮邛，规矩是"三十年只铸一把剑"——替他寻来一块玄铁，看一场好炉火。', target:{type:'collect', what:'玄铁', need:1}, reward:{exp:100,gold:80,item:'游鱼剑'}, turnin:'阮邛',
    acceptLines:['（阮邛蹲在炉边，用火钳拨着炭火，火星子噼啪作响）老夫的规矩，你听说了？三十年，只铸一把剑。','（他抬起眼，瞳仁里映着火光）这一把，炉火已经候了二十九年。就差一块好铁——玄铁，你替老夫寻一块来。'],
    acceptOptions:[
      { text:'三十年一剑——我替你把这块铁寻来。', effect:function(){ log('（阮邛咧嘴一笑，难得地露出几分赞许）懂剑的人，才懂等。','npc','阮邛'); }, aff:10, fame:2 },
      { text:'为何非要三十年铸一把？', effect:function(){ log('（阮邛望着炉火，沉默片刻）剑有剑的命。急火炼出来的，是凶器；慢火养出来的，才是剑。','npc','阮邛'); }, aff:8, exp:30 },
      { text:'一块玄铁可不便宜——报酬先说清。', effect:function(){ log('（阮邛哼了一声）铸成的剑，送你一柄。嫌亏，另请高明。','npc','阮邛'); }, gold:20, aff:-4 }
    ],
    turnLines:['（你从矿脉带回玄铁，阮邛接过去掂了掂，又凑到火光下细看纹理，半晌，重重一点头）好铁。','（他把它放进炉膛，风箱呼啦呼啦地响起来，火星溅了他一身，他却像是没感觉）剑成之日，你来看火。'],
    turnOptions:[
      { text:'这炉火，我记下了。', effect:function(){ log('（阮邛头也不抬：记下就好。剑这东西，等得起。','npc','阮邛'); }, bonus:{fame:4, aff:6, affNpc:'阮邛'} },
      { text:'剑成之后，能不能也替阮秀打一把？', effect:function(){ log('（阮邛的动作顿了一下，声音忽然低了下去）……秀儿不铸剑。她这辈子，不该只围着炉火转。','npc','阮邛'); }, bonus:{expMul:1.3, aff:8, affNpc:'阮邛'} }
    ] },
  '护犊':{ title:'李二的拳头', giver:'李二', desc:'李二的儿子李槐在山崖书院读书——替他去看一眼，看看那小子有没有被人欺负。', target:{type:'talk', what:'李槐', need:1}, reward:{exp:70,gold:60}, turnin:'李二',
    acceptLines:['（李二蹲在墙根，拇指粗的旱烟杆子敲了敲鞋底，闷声道）俺儿子李槐，在山崖书院读书。','（他抬眼，眼神像头护崽的老牛）俺大字不识一个，帮不上忙——你替俺去看看，那小子有没有受人欺负。有人欺负他，你回来告诉俺。'],
    acceptOptions:[
      { text:'虎父无犬子，我去看看。', effect:function(){ log('（李二咧开嘴，难得地笑了：那是！俺儿子，皮实！','npc','李二'); }, aff:8 },
      { text:'书院里都是读书人，谁会欺负他？', effect:function(){ log('（李二哼了一声：读书人？读书人打起架来，更阴！','npc','李二'); }, aff:4, exp:20 },
      { text:'跑腿费先给够。', effect:function(){ log('（李二摸出几枚铜板，又放回去，闷声道：先欠着。俺李二从不赖账。','npc','李二'); }, aff:-2, gold:10 }
    ],
    turnLines:['（你从山崖书院回来，李二还蹲在老地方，烟杆子已经熄了）见着那小子了？','（他盯着你，半天没说话，最后闷声道）他没瘦？没饿着？没让人堵墙角？'],
    turnOptions:[
      { text:'好着呢——他还跟人争"读书人该不该持剑"，中气十足。', effect:function(){ log('（李二嘿嘿乐了，搓了搓手：好小子！像他爹！','npc','李二'); }, bonus:{fame:3, aff:10, affNpc:'李二'} },
      { text:'书没读多少，倒是跟人学坏了嘴皮子。', effect:function(){ log('（李二脸色一沉，旋即又缓和下来，叹了口气）学坏……也比饿着强。','npc','李二'); }, bonus:{expMul:1.2, aff:4, affNpc:'李二'} }
    ] },
