    ] },
  '虎头帽的孩子':{ title:'白也的酒', giver:'白也', desc:'大骊京城里那个头戴虎头帽的少年——他说，诗要配酒。替他寻一壶陈年女儿红。', target:{type:'item', what:'陈年女儿红', need:1}, reward:{exp:180,item:'悟道茶叶'}, turnin:'白也',
    acceptLines:['（虎头帽少年把玩着那枚剑鞘，头也不抬）听说云来客栈有陈年女儿红——天下第一等的酒。','（他抬起头，眼神老气横秋，与那张少年面孔极不相称）寻一壶来，我念你一首诗。一字一句，都是剑意。'],
    acceptOptions:[
