'铸剑':{ title:'三十年一剑', giver:'阮邛', desc:'骑龙巷的铁匠阮邛，规矩是"三十年只铸一把剑"——替他寻来一块玄铁，看一场好炉火。', target:{type:'collect', what:'玄铁', need:1}, reward:{exp:100,gold:80,item:'游鱼剑'}, turnin:'阮邛',
  acceptLines:['（阮邛蹲在炉边，用火钳拨着炭火，火星子噼啪作响）老夫的规矩，你听说了？三十年，只铸一把剑。','（他抬起眼，瞳仁里映着火光）这一把，炉火已经候了二十九年。就差一块好铁——玄铁，你替老夫寻一块来。'],
  acceptOptions:[
    { text:'三十年一剑——我替你把这块铁寻来。', effect:function(){ log('（阮邛咧嘴一笑，难得地露出几分赞许）懂剑的人，才懂等。','npc','阮邛'); }, aff:10, fame:2 },
    { text:'为何非要三十年铸一把？', effect:function(){ log('（阮邛望着炉火，沉默片刻）剑有剑的命。急火炼出来的，是凶器；慢火养出来的，才是剑。','npc','阮邛'); }, aff:8, exp:30 },
    { text:'一块玄铁可不便宜——报酬先说清。', effect:function(){ log('（阮邛哼了一声）铸成的剑，送你一柄。嫌亏，另请高明。','npc','阮邛'); }, gold:20, aff:-4 }
  ],
  turnLines:['（你从矿脉带回玄铁，阮邛接过去掂了掂，又凑到火光下细看纹理，半晌，重重一点头）好铁。','（他把它放进炉膛，风箱呼啦呼啦地响起来，火星溅了他一身，他却像是没感觉）剑成之日，你来看火。'],
  turnOptions:[
    { text:'这炉火，我记下了。', effect:function(){ log('（阮邛头也不抬：记下就好。剑这东西，等得起。','npc','阮邛'); }, bonus:{fame:4, aff:6, affNpc:'阮邛'} },
    { text:'剑成之后，能不能也替阮秀打一把？', effect:function(){ log('（阮邛的动作顿了一下，声音忽然低了下去）……秀儿不铸剑。她这辈子，不该只围着炉火转。','npc','阮邛'); }, bonus:{expMul:1.3, aff:8, affNpc:'阮邛'} }
  ] },
'护犊':{ title:'李二的拳头', giver:'李二', desc:'李二的儿子李槐在山崖书院读书——替他去看一眼，看看那小子有没有被人欺负。', target:{type:'talk', what:'李槐', need:1}, reward:{exp:70,gold:60}, turnin:'李二',
  acceptLines:['（李二蹲在墙根，拇指粗的旱烟杆子敲了敲鞋底，闷声道）俺儿子李槐，在山崖书院读书。','（他抬眼，眼神像头护崽的老牛）俺大字不识一个，帮不上忙——你替俺去看看，那小子有没有受人欺负。有人欺负他，你回来告诉俺。'],
  acceptOptions:[
    { text:'虎父无犬子，我去看看。', effect:function(){ log('（李二咧开嘴，难得地笑了：那是！俺儿子，皮实！','npc','李二'); }, aff:8 },
    { text:'书院里都是读书人，谁会欺负他？', effect:function(){ log('（李二哼了一声：读书人？读书人打起架来，更阴！','npc','李二'); }, aff:4, exp:20 },
    { text:'跑腿费先给够。', effect:function(){ log('（李二摸出几枚铜板，又放回去，闷声道：先欠着。俺李二从不赖账。','npc','李二'); }, aff:-2, gold:10 }
  ],
  turnLines:['（你从山崖书院回来，李二还蹲在老地方，烟杆子已经熄了）见着那小子了？','（他盯着你，半天没说话，最后闷声道）他没瘦？没饿着？没让人堵墙角？'],
  turnOptions:[
    { text:'好着呢——他还跟人争"读书人该不该持剑"，中气十足。', effect:function(){ log('（李二嘿嘿乐了，搓了搓手：好小子！像他爹！','npc','李二'); }, bonus:{fame:3, aff:10, affNpc:'李二'} },
    { text:'书没读多少，倒是跟人学坏了嘴皮子。', effect:function(){ log('（李二脸色一沉，旋即又缓和下来，叹了口气）学坏……也比饿着强。','npc','李二'); }, bonus:{expMul:1.2, aff:4, affNpc:'李二'} }
  ] },
'米粒的瓜子':{ title:'米粒大的心事', giver:'周米粒', desc:'落魄山右护法周米粒，只想吃一把瓜子——替她寻三份干粮来。', target:{type:'collect', what:'干粮', need:3}, reward:{exp:80,item:'谷雨钱'}, turnin:'周米粒',
  acceptLines:['（周米粒叉着腰，仰着小圆脸，一本正经）本护法今天巡山，巡到一半，饿了！','（她掰着手指头）陈山主说了，山上的规矩是——饿了就吃！你给本护法寻三份干粮来，本护法封你当临时左护法！'],
  acceptOptions:[
    { text:'左护法之位，我记下了。', effect:function(){ log('（周米粒满意地点点头：好！本护法说话算话！','npc','周米粒'); }, aff:8 },
    { text:'你一个大水怪，吃干粮？', effect:function(){ log('（周米粒瞪圆了眼：大水怪怎么啦！大水怪也要吃干粮！还要配瓜子！','npc','周米粒'); }, aff:4, exp:15 },
    { text:'左护法能领俸禄吗？', effect:function(){ log('（周米粒认真想了想：俸禄？山上的规矩……瓜子管够！','npc','周米粒'); }, aff:2, gold:10 }
  ],
  turnLines:['（你拎着干粮回来，周米粒眼睛瞬间亮了，一把抢过，蹲在墙角嘎嘣嘎嘣吃得腮帮子鼓鼓的）','（她含糊不清地嘟囔）本护法说话算话——从今儿起，你归本护法罩着了！'],
  turnOptions:[
    { text:'右护法大人慢用。', effect:function(){ log('（周米粒仰起油亮亮的小脸，一本正经：嗯！你很有前途！','npc','周米粒'); }, bonus:{fame:2, aff:12, affNpc:'周米粒'} },
    { text:'我也饿了——分我一半？', effect:function(){ log('（周米粒护食地抱住干粮，犹豫了半天，还是掰了一半递过来：……就一半！','npc','周米粒'); }, bonus:{expMul:1.2, aff:10, affNpc:'周米粒'} }
  ] },
'真龙的明珠':{ title:'龙珠所化的姑娘', giver:'稚圭', desc:'宋集薪的婢女稚圭，想要一颗夜明珠——她说，是替公子镇宅用的。', target:{type:'item', what:'夜明珠', need:1}, reward:{exp:120,gold:150}, turnin:'稚圭',
  acceptLines:['（稚圭垂着眼帘，手指绞着衣角，声音轻得像风）……听说蛮荒游商手里有夜明珠。','（她顿了顿，终于抬眼，那双瞳仁深处，隐隐有一线金光）你若能替我寻一颗来，我……我记你这份情。'],
  acceptOptions:[
    { text:'一颗夜明珠，我去寻来。', effect:function(){ log('（稚圭轻轻点头，又垂下眼帘：多谢。','npc','稚圭'); }, aff:6 },
    { text:'你要夜明珠做什么？', effect:function(){ log('（她沉默了很久，才轻声道：夜里……睡不着。','npc','稚圭'); }, aff:8, exp:25 },
    { text:'替公子镇宅？骗谁呢。', effect:function(){ log('（稚圭倏地抬眼，瞳中金光一闪而逝，又恢复那副怯生生的模样：……你多心了。','npc','稚圭'); }, aff:-4, gold:20 }
  ],
  turnLines:['（你取出夜明珠的刹那，稚圭的呼吸明显顿了一下。她伸手接过，指尖在珠面上轻轻一触，那珠子竟隐隐泛起一圈金光）','（她将珠子拢进袖中，声音低低的）……世间最后一条真龙，总得有点亮晶晶的东西垫着睡觉。这话，你当没听见。'],
  turnOptions:[
    { text:'真龙……我记住了。', effect:function(){ log('（稚圭盯着你看了很久，忽然轻轻笑了一下：你倒是个有趣的人。','npc','稚圭'); }, bonus:{fame:4, aff:12, affNpc:'稚圭'} },
    { text:'你睡觉还要垫夜明珠？奢侈。', effect:function(){ log('（稚圭理直气壮：龙，就是要睡在亮晶晶的东西上。','npc','稚圭'); }, bonus:{expMul:1.2, aff:8, affNpc:'稚圭'} }
  ] },
'虎头帽的孩子':{ title:'白也的酒', giver:'白也', desc:'大骊京城里那个头戴虎头帽的少年——他说，诗要配酒。替他寻一壶陈年女儿红。', target:{type:'item', what:'陈年女儿红', need:1}, reward:{exp:180,item:'悟道茶叶'}, turnin:'白也',
  acceptLines:['（虎头帽少年把玩着那枚剑鞘，头也不抬）听说云来客栈有陈年女儿红——天下第一等的酒。','（他抬起头，眼神老气横秋，与那张少年面孔极不相称）寻一壶来，我念你一首诗。一字一句，都是剑意。'],
  acceptOptions:[
    { text:'一壶酒，换一首诗——值。', effect:function(){ log('（白也微微一笑：识货。','npc','白也'); }, aff:8, fame:2 },
    { text:'诗能当饭吃？', effect:function(){ log('（白也悠然道：诗不能当饭吃——但能当剑使。','npc','白也'); }, aff:6, exp:25 },
    { text:'先付钱，后打酒。', effect:function(){ log('（白也摸了摸袖子，摸出一枚铜钱，又放回去：……先赊着。白也从不赖账。','npc','白也'); }, aff:-2, gold:20 }
  ],
  turnLines:['（你把酒壶放在石桌上，白也放下剑鞘，拔开壶塞闻了闻，眯起眼，半晌没说话）','（他忽然拍案而起，朗声笑道）"且就洞庭赊月色，将船买酒白云边"——好酒！好酒！这一首，算你的！'],
  turnOptions:[
    { text:'好诗！这一壶，值了。', effect:function(){ log('（白也大笑，又给自己倒了一碗：值不值，喝了才知道。','npc','白也'); }, bonus:{fame:6, aff:12, affNpc:'白也'} },
    { text:'诗我记下了——可你是谁？', effect:function(){ log('（白也摸了摸虎头帽，笑意淡了些：我是谁……等这顶帽子摘下来那天，你自然知道。','npc','白也'); }, bonus:{expMul:1.3, aff:6, affNpc:'白也'} }
  ] },
