// 武侠诗句副标题
applyWuxiaSubs();
// 全局错误捕获（仿 LPMUD master apply「log_error」：出错即记录，便于反馈修复）
try{
  window.addEventListener('error',function(ev){
    try{
      const box=document.getElementById('log');
      if(box){
        const d=document.createElement('div');
        d.className='msg';
        d.innerHTML='<span class="line warn" style="color:#e8963f;">（系统日志：'+(ev.message||'未知错误')+(ev.filename?' @ '+ev.filename.split('/').pop()+(ev.lineno?':'+ev.lineno:''):'')+'）</span>';
        box.appendChild(d);
        while(box.children.length>100 && box.firstChild){ box.removeChild(box.firstChild); }
      }
    }catch(e2){}
  });
}catch(e){}
// 音乐系统
startMusicLoop();
enableAudioOnGesture();

